CREATE TABLE planet_properties_earth_units (
    planetref BIGINT PRIMARY KEY,
    mass_earth REAL,
    radius_earth REAL
);

WITH gravities AS (
    SELECT planetref, mass_earth / (radius_earth * radius_earth) as surface_gravity 
    FROM planet_properties_earth_units 
    WHERE radius_earth IS NOT NULL AND mass_earth IS NOT NULL
)
SELECT planetref FROM gravities ORDER BY surface_gravity DESC LIMIT 1;
